using UnityEngine;

public class Shooter : MonoBehaviour
{
    [SerializeField] private GameObject bulletPrefab;
    [SerializeField] private Transform firePoint;
    [SerializeField] private float bulletSpeed = 20f;

    void Update()
    {
        if (Input.GetKeyDown(KeyCode.Space))
        {
            SpawnBullet();
        }
    }

    void SpawnBullet()
    {
        // Instantiate(prefab) — en la posición y rotación del prefab original
        // GameObject obj = Instantiate(bulletPrefab);

        // Instantiate(prefab, position, rotation) — forma más común
        GameObject bullet = Instantiate(bulletPrefab, firePoint.position, firePoint.rotation);

        // Guardar la referencia para manipular la instancia
        Rigidbody rb = bullet.GetComponent<Rigidbody>();
        if (rb != null)
        {
            rb.linearVelocity = firePoint.forward * bulletSpeed;
        }

        // Instantiate con parent: el nuevo objeto será hijo del transform indicado
        // GameObject bullet2 = Instantiate(bulletPrefab, firePoint.position, firePoint.rotation, transform);
    }
}

using UnityEngine;

public class Bullet : MonoBehaviour
{
    [SerializeField] private float lifetime = 3f;

    void Start()
    {
        // Destroy con delay: elimina el objeto después de N segundos
        Destroy(gameObject, lifetime);
    }

    void OnCollisionEnter(Collision collision)
    {
        // Destroy(gameObject): elimina el objeto inmediatamente
        Destroy(gameObject);

        // Destroy(this): elimina SOLO este componente, el GameObject sigue existiendo
        // Destroy(this);

        // Destroy otro objeto:
        // Destroy(collision.gameObject);
    }
}

// Spawner: crea enemigos periódicamente
public class EnemySpawner : MonoBehaviour
{
    [SerializeField] private GameObject enemyPrefab;
    [SerializeField] private float spawnInterval = 2f;
    private float timer;

    void Update()
    {
        timer += Time.deltaTime;
        if (timer >= spawnInterval)
        {
            timer = 0f;
            Vector3 pos = new Vector3(Random.Range(-5f, 5f), 0, 0);
            Instantiate(enemyPrefab, pos, Quaternion.identity);
        }
    }
}

